#!/usr/bin/env node
/**
 * Generate the demo avatar portraits (`apps/web/public/avatars/<id>.svg`).
 *
 * Owner's call (2026-10-13): people on screen should look like people, not
 * like two-letter chips. Section 9.7 rules out stock photos, so these are
 * flat illustrated portraits — deterministic per roster id (skin, hair, shirt
 * and backdrop derive from a hash of the id), regenerated by running:
 *
 *   node scripts/gen-avatars.mjs
 *
 * Raw hex lives here, not in feature code: `scripts/**` is the one place the
 * ESLint no-raw-colour rule is off, and the outputs are static SVG assets.
 * Adding a roster row? Re-run this script; the file name is the person id.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ROSTER } from '../apps/web/src/mocks/roster.js';

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'apps', 'web', 'public', 'avatars');

/** Muted backdrop pairs (indigo / violet / teal / marigold / rose families). */
const BACKDROPS = [
  ['#E8ECFF', '#D9D5FF'],
  ['#F1E9FF', '#E4D4FF'],
  ['#E0F2F1', '#CDE8E6'],
  ['#FDEEE0', '#F8DCC4'],
  ['#FCE7F0', '#F5D0E1'],
  ['#E7EEFB', '#D3E2F7'],
];

const SKINS = ['#F6D7B8', '#EFC08F', '#D9A066', '#B07B4F'];
const SKIN_SHADES = ['#E8C2A0', '#DFAE7C', '#C48D55', '#9A6A41'];
const HAIRS = ['#2E2A26', '#4A3423', '#1F1B16', '#3E2C20', '#59402B'];
const SHIRTS = ['#3F5BE0', '#7C5CD6', '#2F8F83', '#C2703A', '#B5466F', '#41567A'];

/** FNV-1a over the id → stable picks, so a rebuild never reshuffles faces. */
function hash(id) {
  let h = 0x811c9dc5;
  for (let i = 0; i < id.length; i += 1) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

const pick = (list, h, shift) => list[(h >>> shift) % list.length];

/** Hair shapes: short cap · bun · long · curly. Drawn over a 12r head at 32,28. */
const HAIR_SHAPES = [
  '<path d="M20 28c0-8 5.4-12.5 12-12.5S44 20 44 28h-2.6c0-5.2-4-8.2-9.4-8.2s-9.4 3-9.4 8.2Z" fill="HAIR"/>',
  '<path d="M20 28c0-8 5.4-12.5 12-12.5S44 20 44 28h-2.6c0-5.2-4-8.2-9.4-8.2s-9.4 3-9.4 8.2Z" fill="HAIR"/><circle cx="32" cy="12.5" r="4.2" fill="HAIR"/>',
  '<path d="M19.4 27c0-8.6 5.7-13.2 12.6-13.2S44.6 18.4 44.6 27v14a3 3 0 0 1-3 3h-1.4V27.6c0-5-3.2-8.2-8.2-8.2s-8.2 3.2-8.2 8.2V44h-1.4a3 3 0 0 1-3-3Z" fill="HAIR"/>',
  '<circle cx="24.5" cy="19" r="5.4" fill="HAIR"/><circle cx="32" cy="15.6" r="5.8" fill="HAIR"/><circle cx="39.5" cy="19" r="5.4" fill="HAIR"/><path d="M21.6 24.5h20.8v3.6H21.6Z" fill="HAIR"/>',
];

function portrait(id) {
  const h = hash(id);
  const [bg1, bg2] = pick(BACKDROPS, h, 0);
  const skin = pick(SKINS, h, 4);
  const shade = pick(SKIN_SHADES, h, 4);
  const hair = pick(HAIRS, h, 8);
  const shirt = pick(SHIRTS, h, 12);
  const shape = pick(HAIR_SHAPES, h, 16).replaceAll('HAIR', hair);

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" role="img" aria-label="${id}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${bg1}"/>
      <stop offset="1" stop-color="${bg2}"/>
    </linearGradient>
  </defs>
  <rect width="64" height="64" rx="32" fill="url(#bg)"/>
  <path d="M12 64c0-11 9-17.6 20-17.6S52 53 52 64Z" fill="${shirt}"/>
  <rect x="28" y="34.5" width="8" height="11" rx="4" fill="${shade}"/>
  <circle cx="32" cy="28" r="12" fill="${skin}"/>
  ${shape}
  <circle cx="27.6" cy="28.6" r="1.35" fill="#2E2A26"/>
  <circle cx="36.4" cy="28.6" r="1.35" fill="#2E2A26"/>
  <path d="M29 33.4c1.8 1.5 4.2 1.5 6 0" stroke="#2E2A26" stroke-width="1.4" stroke-linecap="round" fill="none"/>
</svg>
`;
}

const ids = ROSTER.map((person) => person.id);
mkdirSync(OUT_DIR, { recursive: true });
for (const id of ids) {
  writeFileSync(join(OUT_DIR, `${id}.svg`), portrait(id));
}
console.log(`wrote ${ids.length} portraits to apps/web/public/avatars/`);
